const input=$json.body??$json;
const status=String(input.coordination_status??input.status??'').toLowerCase();
const dealId=input.deal_id,leadId=input.lead_id,propertyId=input.property_id;
const closingDate=String(input.closing_date??'').trim();
const roles=input.coordination_roles??{};
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const milestones=Array.isArray(input.milestones)?input.milestones:[];
const identityReady=Boolean(dealId&&leadId&&propertyId);
const rolesReady=Boolean(roles.title&&roles.attorney&&roles.funding&&roles.broker);
let daysRemaining=null;
if(closingDate){const d=new Date(closingDate);if(!Number.isNaN(d.getTime()))daysRemaining=Math.ceil((d.getTime()-Date.now())/86400000);}
let milestone_status='needs_review',next='WF-126',reason='closing milestone monitoring requires review';
if(input.dnc===true){milestone_status='blocked_dnc';reason='DNC/contact restriction';}
else if(blockers.length){milestone_status='blocked';reason='active closing blockers';}
else if(status!=='coordination_ready'){milestone_status='coordination_not_ready';next='WF-324';reason='closing coordination is not confirmed';}
else if(!identityReady||!closingDate){milestone_status='incomplete';reason='deal/property/lead identity or closing date missing';}
else if(!rolesReady){milestone_status='coordination_incomplete';next='WF-324';reason='required closing coordination roles are incomplete';}
else if(daysRemaining!==null&&daysRemaining<0){milestone_status='overdue';next='WF-326';reason='closing date has passed and requires exception handling';}
else if(daysRemaining!==null&&daysRemaining<=3){milestone_status='critical_due_soon';next='WF-326';reason='closing is within 3 days';}
else if(milestones.length&&milestones.every(m=>String(m.status??'').toLowerCase()==='completed')){milestone_status='milestones_completed';next='WF-326';reason='all supplied closing milestones are completed';}
else{milestone_status='on_track';next='WF-326';reason='closing coordination validated and milestone monitoring is active';}
return [{json:{...input,workflow_id:'WF-325',workflow_name:'Closing Coordination → Critical Dates & Milestone Monitoring Controller',milestone_status,reason,deal_id:dealId,lead_id:leadId,property_id:propertyId,closing_date:closingDate||null,days_remaining:daysRemaining,coordination_roles:roles,milestones,next_workflow:next,human_review_required:['blocked_dnc','blocked','incomplete','coordination_incomplete','overdue'].includes(milestone_status),crm_activity:{activity_type:'closing_milestone_monitoring',deal_id:dealId,lead_id:leadId,property_id:propertyId,status:milestone_status,closing_date:closingDate||null,days_remaining:daysRemaining,reason}}}];
